import { h, setChildren } from '../util.js';
import { t, getLang } from '../i18n.js';

// Keep in sync with docs/USER_GUIDE.md (a unit test checks both exist in both languages and mention the current version).
export const GUIDE = {
  en: [
    ['Quick start', ['Open Routines and tap Start on a sample routine, or create your own with “New routine”.', 'Each routine is a list of tasks. Every task has a duration (minutes + seconds) and an optional time estimate.']],
    ['Building a routine', ['Tap a routine to edit it. Drag the ⋮⋮ handle (or use the arrows / Alt+arrow keys) to reorder tasks.', 'Time estimate = your own guess of the real time; leave it empty to use the duration. Defaults live in Settings.', 'The star adds a routine to Favorites - those also appear in the Android home-screen widget.']],
    ['Running a routine', ['Start begins the first task. The ring counts down; at 10 seconds left you get a short beep and when time is up a longer one (change this in Settings: beep, vibrate, both, silent).', '“Done ✓” (or ticking the checkbox) moves on. Pause, +1 min, Skip and Finish are always one tap away. Time keeps counting as “over” until you tap Done.', 'The summary shows start time, planned vs. estimated vs. actual time and each task. A run in progress survives closing the app.']],
    ['Statistics and insights', ['Stats shows every routine you finished: a chart of total time per run (actual, planned, estimate), averages and a per-task table.', 'After 3 runs you get insights: tasks that always finish early (shorten) or late (extend), and the net effect on the total frame. Tap Apply to update the duration.']],
    ['Start alarm', ['Wake-up alarms: in the editor switch on “Remind me to start”, choose time and days. The first alarm has its own sound, volume, vibration, length and message; “Add another alarm” (or “Add N more alarms every M minutes”) adds more, each after a gap you choose and each with its own sound, volume, message and optional spoken voice - for example 7:00, 7:15 and 7:20. After the last alarm choose “Offer to start” (a Start button) or “Start the routine automatically”. Android: real alarms that ring even when the app is closed; on a locked phone the app opens by itself, otherwise tap the notification (its Start button always starts). Browser: only while the page is open.']],
    ['Unplanned interruptions', ['Unplanned interruptions: during a routine tap ⚡ Unplanned and pick what happened (toilet, spilled drink, forgot something... or your own words). The routine clock stops and that time is counted on its own - not as task time and not as a pause - then tap “Back to the routine”. The summary and Stats show how often and how long. When the same interruption keeps coming back in a routine (in at least 3 of the last runs) a card offers to add it to the routine as a real task, or to look closer: a few guiding questions (why, what happens before, one thing to try) are saved in your journal and the app keeps counting to show whether it changes.']],
    ['Sharing', ['Share creates a code and a link. Send it with the system share sheet (Bluetooth, Nearby Share, WhatsApp), copy it, or write it to an NFC tag. Import accepts a code, link, text file or an NFC tag.', 'There is no server: everything is transferred directly and checked on arrival.']],
    ['Encouragement, stars and screen', ['Settings → Name and My buddy: the app cheers you on by name with cheerful messages, emojis and little animations (turn off or have them read aloud in Settings).', 'Finish a routine to earn up to 3 stars (all done within the plan = 3). Finishing at least one routine a day builds a 🔥 streak shown on the home screen.', 'Pause is the big button next to Done: the clock stops and the paused time is shown in the summary. The ☀️ chip on the home screen (or Settings) keeps the screen on while the app is open so you can tap progress any time.']],
    ['Mindful coach and voice', ['Settings → About you: add your name, age and gender - messages and tips then speak to you (Hebrew uses the right masculine/feminine forms) in a tone that fits your age.', 'Tap 💡 Tip (next to Pause) or the 💡 on any task to get a short CBT / mindfulness idea: breathing, grounding, checking worried thoughts, letting thoughts pass, kindness to yourself, focus, time pressure. Tap “Another tip” for a new one.', 'Switch on “Automatic tips” and the coach offers a tip when a task runs over, you are 3+ minutes behind, or you stayed paused for 2 minutes. Under Settings → Voice choose whether encouragement and tips are text only or also spoken automatically (same tone, name and gender forms), then pick a voice and a style (deep, high, robot, chipmunk, giant, sleepy, superhero, fairy). Styles change pitch and speed of your phone’s voice; install a Hebrew voice in the phone’s Text-to-speech settings if none is found.', 'The coach gives general wellbeing ideas, not treatment. If worry feels overwhelming, talk to a trusted adult or a professional.']],
    ['Moving data between the app and the website', ['The website (PWA) and the Android app keep their data separately. To move routines, history and settings between them: Settings → Move data → Save backup file / Copy sync code / Send…, then on the other one → Import backup (file, or paste the code).', 'Merge keeps the newest version of every routine and adds missing history; it never deletes. Replace makes this device an exact copy of the backup. Tick “Also import settings” to bring your name, voice and preferences too.']],
    ['Leave time, pace and accessibility', ['In the editor set “Leave by”: the run shows whether you will make it (spare time or late) and warns 10 and 5 minutes before. “Suggest start time” sets the start alarm so you finish exactly in time.', 'Settings → Pace: Quick shortens every task by 30%; Calm hides warnings and red “over” states so there is no time pressure. “Say the next task out loud” reads “Now: …” at each task.', 'Settings → Accessibility: text size, color-blind friendly colors, high contrast and screen-reader announcements (TalkBack). Tasks can have a sticker or your own photo (tap the task icon).']],
    ['Family: parent and child phones', ['Open the Family tab. On the parent’s phone tap “Add a child” and give the invitation to the child’s phone: tap the two phones together (NFC, Android app), write it to an NFC tag, send it by Bluetooth / Nearby Share / a messenger, or copy it. On the child’s phone tap “Join a parent”, paste the invitation and send the reply back; the parent approves. An invitation works once and expires after 24 hours. It can also be shown as a QR code for the other phone to scan.', 'Once linked, the parent sees the child’s stars, streak, recent routines and what they are doing right now; sends routines, cheers and a reward goal (20 stars = ice cream, or “5 on-time routines this week”) and gets an alert when the child is running late (over a live link). When the goal is reached the child celebrates and the parent is told.', 'There is no server: messages are encrypted and travel directly. With “Connect live (Wi-Fi)” (both phones on the same network) or the Android app’s Bluetooth link (pair the phones first) updates are instant; otherwise each message is a code you pass on by NFC tag, share sheet or copy-paste.']],
    ['Progress widget (Android)', ['Add the “Routine progress” widget from the home screen: it shows the routine in progress, the current task, a live countdown and a progress bar, and opens the app when tapped.']],
    ['Simple mode, accent color and settings', ['Settings → Appearance → “Simple mode for kids” shows only the routines with big Start buttons. Everything else (editing, settings, statistics, family) is locked behind a quick grown-up question for 10 minutes at a time.', 'Pick an accent color for the whole app, plus light/dark theme, text size, color-blind friendly colors and high contrast. Settings are grouped into sections you can collapse; the app remembers which are open.']],
    ['Weekly summary, history and examples', ['Stats shows “This week”: routines finished, stars, on-time count, active days and whether you got faster than last week, plus a 5-week calendar heat-map. “Share summary” sends a short text; “Export history (CSV)” saves every run for a spreadsheet.', 'Deleting a routine offers “Undo” for a few seconds. Settings → “Add more example routines” adds bedtime, homework and after-school routines.']],
    ['People, avatars and levels', ['Several people can share one phone: tap the avatar on the home screen (or Settings → About you) to switch person or add one. Each person has their own name, age, avatar, routines history, stars, streak, badges and parent link.', 'Pick an avatar: animated characters (they blink, wave, cheer, dance and sleep as you go - fox, cat and panda from the start, more unlock as you level up), an emoji, your own photo, or your own animated GIF (up to 160 KB). Photos and GIFs stay on your phone.', 'Stars raise your level (shown on the home screen); higher levels unlock new characters.']],
    ['Days, gear and achievements', ['In the editor, “Schedule” sets which days a routine is for (school days, weekend or any days); the home screen lists today’s routines first. “Gear to remember” adds things for certain days (PE kit, swimming bag): they appear as a checklist when you start and are counted in the summary.', 'Badges (first routine, streaks, on time, early bird, speedy, comeback…) are earned automatically; new ones are celebrated on the summary screen and all of them are in Stats → Achievements.']],
    ['Android app and widget', ['Routine card widget: add “Routine card” from the widgets list. It shows one saved routine with its tasks, durations, days, leave-by time and gear count; tap it (or ▶ Start) to run it in the app with all its saved settings. Use ‹ › on the widget to show a different routine (each widget remembers its own). While that routine runs the card becomes a live countdown with progress.', 'Settings → Download Android app always gives the latest APK. Allow “install unknown apps” for your browser once.', 'Long-press the home screen → Widgets → SonRise to start a favourite routine in one tap.']],
    ['Helpers: calm, focus, journal and rewards', ['Choose what you want help with: Home → “What would you like help with?” (or Settings → Helpers). Pick areas such as focus, calm, time sense, remembering, motivation or habits - the app switches on matching tools. A parent can choose this for a child from the Family tab (🎯). Every tool can still be switched on or off on its own.', 'Calm corner (🌬️): breathing patterns, 5-4-3-2-1 grounding and a body scan, 1-3 minutes, with a gentle vibration cue. During a routine it pauses the clock while you breathe. Focus sprints split long tasks into short sprints with a 30-second movement break; the parking lot (🅿️) saves a stray thought so you can get back to the task; the next-task heads-up shows what comes next; the pie timer shows time as a filling circle; the mood faces after a routine feed a mood insight in Stats.', 'Journal (📓): notes, voice notes (🎙️ - recorded during a task too), thought checks, “3 good things” and parked thoughts. It is stored only on this device and is not part of backups or sharing. Password (optional): Journal → Password. It is stored as a salted hash and the entries are encrypted; adding a note never needs the password. Forgot it? Answer your two security questions to set a new one. If you forget both, entries cannot be opened - you can only erase them.', 'Speech to text (optional): in a note tap “Dictate” (or record - in a browser a suggested transcript appears while you speak). It is only a suggestion: check and edit it. In the Android app it uses the phone’s own recognizer; in a browser the browser’s speech service may send audio to its maker, so the app asks first. Reward menu (🎁): spend stars on rewards from a menu you or a parent set up; a parent is told and can mark it as given.']],
    ['Easier editing, wording and extras', ['Editing tasks: tap the time on a task to open the time sheet (quick times, ±1m/±15s buttons, exact minutes and seconds), or use the − / + buttons next to it. The ☰ menu on each task lets you add a task below, duplicate, move up/down/to the top/to the bottom, change the picture or remove it; dragging by the handle still works. If-then plans (editor → “If-then plans”) show as a card when the routine starts: “If I want to scroll my phone, then it goes in the drawer”. Settings → Appearance → “Timer look” switches the ring to a pie, a bar or a sand clock. Young children: with an age under 12 the whole app uses lighter, more fun wording (Settings → Appearance → Wording to force it on or off). Android: the alarm notification has a 5-minute Snooze, and a “Calm corner” widget opens breathing in one tap. Parents see a weekly digest (slowest steps, repeated interruptions) on each child’s card.']],
    ['Templates', ['Templates: save tasks and routines you use again and again. In a routine’s editor tap “Save as template” (💾) for the whole routine, or “Save task as template” in a task’s ☰ menu. “Add from templates” opens big tiles of your saved tasks and ready-made ideas (morning, evening, school, home) - search, filter, and tap as many as you like. On the home screen “From a template” starts a new routine from one of your templates or a ready-made idea. Home → Templates manages them: use, rename, edit time, share, delete (with Undo). Templates are included in “Back up all data” and sync codes.']],
    ['Goals', ['Goals (Goal - Plan - Do - Check): Home → Goals. Write one goal that matters to you (“be ready on time without reminders”), optionally tie it to a routine, and choose up to three strategies that fit you - for time, planning, remembering, attention or organising - or write your own. Do: the plan appears as a card when you start that routine. Check: after the routine tell the app how it worked (a face and a few words); the app shows how many routines were on time since you began and whether your check-ins are getting better, and prompts a weekly check-in. A parent can suggest a goal from the Family tab (“Suggest a goal”), and “Sit with me” shows the child that the parent is with them during a routine. Inspired by goal-based, strategy-focused approaches such as Cog-Fun (Hebrew University occupational therapy). It is a self-help tool and does not replace an occupational therapist or other professional.']],
    ['Alarms screen', ['Alarms screen: Home → Alarms lists every routine with its wake-up alarm - switch it on or off, see the schedule (e.g. 07:00 → 07:15 → 07:20) and edit the whole chain. Each routine card also shows its alarm. After an update a one-time “New in…” sheet points to new features.']],
    ['Task feelings and help', ['Feelings and help on every task: while you do a task, rate how hard it is with the icons (🪶 very easy … 🥵 very hard). “Why is it hard?” opens a note (type or record) with that task attached - what is hard and which thoughts came up. “A kind thought” and “Relax” give a different suggestion each time, worded for your age: kind thoughts (effort, self-compassion, reframing, starting small) and short exercises (breathing, squeezing and releasing, shaking out, five senses, butterfly hug and more); breathing exercises can open the Calm corner. Everything is saved with the run. Stats → “Where is it hard?” ranks tasks by average difficulty, flags the ones that are both hard and slow, and counts how often notes, kind thoughts and relaxation were used - so you can see where more help is needed.']],
    ['Reports, PDF and e-mail', ['Reports, PDF and e-mail: Stats → “Export & send” (or 📄 next to any run in a routine’s history, or on the summary screen) opens a designed report with a summary, insights in plain words, charts over time, an activity calendar, per-routine and per-task tables, difficulty, interruptions, mood and goals - for one run or for the last 7/30/90 days or all time, for all routines or one. “Save as PDF” makes a real PDF file; “E-mail the report” opens your e-mail app with the PDF attached (Android app, or phones that support sharing files) - in a browser the PDF is downloaded and the mail opens with a summary, and you attach the file. Print and copy-summary are there too. Reports are made on this device only.']],
    ['Smart times and extra steps', ['Smart times and extra steps: in a routine’s editor, “Smart times” suggests a duration for every task - from your own past runs when there are some (typical time, a little more if it usually runs over), otherwise a sensible estimate for that kind of task adjusted for age and the help you chose (focus, calm, time, remembering). A small “about 8m” hint also appears under a task name. “Smart extra steps” proposes short in-between steps that fit the help you chose - for anxiety a calming breath at the start and a calm check before something long or hard; for attention picking one thing to start, a movement break after a long stretch, clearing the desk before homework; for memory saying the steps aloud and a last check. Each suggestion shows why; you tick what you want. A parent can choose “Suggest for” a linked child. Steps added this way offer a one-tap exercise when they come up in the run.']],
    ['Cog-Fun tools, version and HTML reports', ['More Cog-Fun-inspired tools: Stats → “How close are my guesses?” compares the time you guessed for tasks with what really happened and says whether you tend to guess short or long and whether you are getting closer. In a goal’s check-in, tick which strategies you used - the goal then shows which one went best. Parents get a daily “Ask, don’t tell” guiding question in the Family tab. Alarms are on by default for new and ready-made routines (Home → Alarms), the version number is shown at the bottom of Home and in Settings, and “What’s new” lists what changed. Reports can also be saved as one interactive HTML file with animations (tabs for 7/30/90 days and all time, numbers counting up, bars and charts drawing themselves, collapsible sections; it works offline and prints well).']],
    ['Looking back', ['Looking back (retrospective): after a run, tap “Look back” on its summary (or 🔄 in a routine’s history, or the prompt on Home - the run with the most going on comes first, and you can do it days later). First choose how: guided (one step at a time, you can stop and continue later) or free (everything on one page); for this run or for the routine’s last 5 runs (the usual picture); the whole thing or only some parts (how it felt, tasks, what went well, what to change) - the rest can be done in another look-back, and you can do as many look-backs as you like for the same run. For each task choose went well, got stuck or not now; where it got stuck pick why (hard to start, distractions, too big or unclear, tired, could not find something, worries, not enough time). The app then suggests concrete changes to this routine - more time, a helper step before it, splitting a task, an earlier alarm, a gear item, planning for an interruption, a goal with a plan - and you apply the ones you tick in one tap (each can be undone). After you apply changes the app compares the routine’s next runs with the earlier ones (on time, over/under the plan, difficulty, stuck tasks, interruptions) and tells you whether it helped, got worse or made no clear change - waiting for 3 runs first, and then a card on Home tells you. Home → Looking back shows what to focus on (tasks that keep getting stuck or were set aside), what worked and what did not, what gets in the way, drafts to finish, and automatic conclusions; Settings → Helpers lets you set your usual style. Results are part of the reports (PDF and HTML) and backups.']],
    ['Alarms, quiet days and the toolbar', ['Alarms, quiet days and the toolbar: Home has one toolbar - New, Wizard, Plan, Calm, Track and Alarms. Plan, Calm and Track open a short list under the bar; Alarms pauses all alarms (until tomorrow, for a week, or until you switch them on). Every routine card has an alarm switch and a ⏰ sticker when it has an alarm. In an alarm, choose the type of ring (tap a tile to hear it; in the Android app also a sound from your phone) and keep "Quiet on holidays and vacations" on to stay silent on Jewish holidays and school vacations, including the summer. Home shows the Hebrew date and today’s holiday.']],
    ['Calm corner: body scans and guided imagery', ['Calm corner: body scans and guided imagery: choose Breathing, 5-4-3-2-1, Body scan or Guided imagery. Body scan has four kinds: quick, full (head to toe), tense and release, and for sleep. Guided imagery has 11 short journeys - the four elements (earth, air, water, fire), a safe place, waves, forest, mountain, leaves on a stream, a worry balloon, a worry box, warm light, a floating cloud and a kind helper - shown one step at a time and, if you like, read aloud. These are relaxation exercises, not treatment.']],
['Situation log (EIER)', ['Situation log (EIER): a way to understand hard moments, from CBT. Four short questions - Event (what happened), Interpretation (what I told myself), Emotion (what I felt, how strong) and Response (what I did) - plus an optional step for another way to see it. Write it, dictate it or record it. Find it in Journal → Reflect, in the task help card (Log this moment), at the end of a calm exercise, or by search. After three logs the journal summarises your patterns (feelings, thinking traps, what eases things). It is private to this device and is a self-help overview, not a diagnosis.']],
['Goals inside routines and the wizard', ['Goals inside routines and the wizard: a goal can be linked to a routine (the routine card shows a 🎯 chip, the editor has a Goal section, and the run screen shows the plan). In the wizard, the Goal step lets you pick or create a goal, and the goal adds its strategies as the first steps of the new routine. In the review step you can rename steps, change their time, remove steps and add your own before creating. From any goal, "Build a routine for this goal" starts the wizard.']],
    ['Start over, cancel or delete a run', ['Start over, cancel or delete a run: a routine in progress is never a dead end. On the run screen open More → Change the plan: Start over begins again from the first task, Cancel this run leaves without saving anything. The same two buttons are on the Home "continue" card. Nothing from a cancelled or restarted run goes into your history. A finished run can be deleted from its summary screen (Delete this run) and brought back with Undo.']],
    ['What the app is for, people and voice commands', ['What the app is for: in Settings → What the app is for, choose a way of working (CBT, Cog-Fun) and/or what is hard (attention, anxiety, getting organised, motivation) and an age, and the app shows only what fits. Show everything brings it all back at any time.', 'People: each person has their own settings, look and view. Switch from the little menu at the top, add people there, or manage everyone in Settings → People. With several people the app can ask who is using it at the start.', 'Settings: a search box and a jump bar are at the top of Settings. Choose a look (skins), easy-read text or your own colour under Look. The welcome and setup screens can be opened again from Settings.', 'Voice commands: during a routine tap Listen for commands and say a short phrase such as done, add time, pause, resume, skip, journal, calm corner, remind me the step, how much time is left or stop (it always asks first; answer yes or no). It keeps listening through all the steps. Tap the ? to see all commands, also listed in Settings → Voice commands.']],
    ['Sharing between people, special tasks, points and moving routines', ['Who sees a routine: when there are several people on the device, open a routine and its “Who sees this routine” section: everyone, or only the people you choose (a parent or therapist can set routines up for the children on one phone). Alarms still ring on the device.', 'Special tasks: in the routine editor tap “Add a special task” and pick by topic or search: write in the journal, park a thought, body scan, guided imagery, relaxation, voice note and more. On the run screen the task shows one big button that opens that tool.', 'Points: Settings → Points and awards. Automatic points follow the planned time, or you set the points of each step. Finishing early adds a bonus, finishing late takes some away (never below 0, never in the calm pace, and you can switch it off). A step can carry an award (medal, coin, trophy, star, gem, crown) that is won by finishing before its time, with double points. At the end a podium with fireworks shows your best scores for that routine; Statistics shows points over time and a running total.', 'Moving routines: Home → Plan → Share and move routines. Copy routines to another person on the device, save them as a file (or send it by WhatsApp or e-mail) and bring routines in from a file for a chosen person. Imported routines come with their alarm switched off.']],
    ['Kids view and full view', ['Next to the “who is using the app” chip at the top there is a button: Kids view switches to the kids’ view (only routines and a big Start) in one tap. In the kids’ view the top bar shows only Full view, which asks a quick grown-up question before it brings everything back. The choice is kept per person.']],
    ['NLP tools and calm animations', ['In Settings → What the app is for you can choose NLP as a way of working, next to CBT and Cog-Fun. Home → Calm → NLP tools lists six short guided exercises: a clear outcome, another way to see it (reframing), a calming anchor, precise words (finding big words like “always” and “can’t”), points of view, and mental rehearsal. Each asks a few questions, one at a time, and can save your answers to the journal. They are also special tasks you can add to a routine; on the run screen the task opens its exercise.', 'NLP is a popular set of coaching techniques, but the research evidence for it is limited and mixed: these are gentle self-reflection exercises, not therapy and not a promise of results. Settings → Accessibility → Calm animations turns off movement such as fireworks, confetti and bouncing.']],
    ['Avatar studio and My avatars', ['Open the avatar picker (Settings → About you → Avatar, or when editing a person) and tap “Build my own”, or open “My avatars”. In the studio a live preview at the top shows your avatar; try its animations (rest, wave, cheer, dance, sleep, surprised, think) and feelings (happy, calm, sad, worried, annoyed, tired, excited, proud). Choose a tab: face, hair, eyes and mouth, clothes, extras, a friend and background, or colours. Options with a lock unlock at higher levels. “Surprise me” picks a random avatar. Give it a name and tap Save, or “Use as my avatar”.', 'My avatars lists your saved designs: use, edit, duplicate, share or delete (undo is right there). Share sends a short code through WhatsApp, e-mail or the clipboard; “Add from a code” shows the avatar before adding it. Saved avatars are part of the backup file.']],
    ['Calm and bold looks', ['Settings → Appearance now also offers Calm (one muted colour family, low stimulation, for people who are overwhelmed by colour) and Bold (strong contrast, a thicker focus ring and borders, for attention difficulties and low vision), in light and dark.']],
    ['Updates and sharing the app', ['Updates and sharing the app: the web app updates itself - when you open it, and every hour - and switches to the new version on its own when nothing is running; if you are in the middle of something it asks first. The Android app updates from the latest download. To share SonRise open Settings → App → Share (or search "share"): choose the Android app or the web app, and send it by WhatsApp, e-mail, the share sheet or a copied link.']],
    ['Search, wizard and suggestions', ['Search, wizard and suggestions: tap 🔍 (bottom bar or Home, or press Ctrl+K) and type what you want, e.g. "alarm", "voice" or a routine name - tap a result to go straight there. The wizard (Home → Help me build one, or search "wizard") asks who it is for, how old, what helps, which routine and when, then builds the routine with fitting times and optional calm / focus breaks. Now and then Home shows one gentle suggestion; choose Try it, Not now or Don’t show this again (Settings can switch suggestions off). Screens are kept calm: look under "More" for the rest of the tools.']],
    ['Voices', ['Voices: Settings → Helpers/Voice. Pick a character: everyday voices (woman, man, girl, boy, grandma, grandpa), speaking styles (coach, calm guide, storyteller, radio host, teacher) or fun characters (cat, dog, lion, frog, pirate, dinosaur, robot, fairy) - animals say their sound first (“meow”). Each character picks a matching installed voice (male or female, the most natural one first, other characters use another voice when your device has more than one), speaks in phrases with natural pauses and rising or falling intonation at a calm human pace, and never reads emoji or abbreviations. You can still choose a specific device voice (★ marks natural/neural ones), set the speaking pace, and a wording style (casual, warm and traditional, polite and formal) that adds a short opener now and then. Choosing anything plays a sample. How human it sounds depends mostly on the voices installed on your device - the settings include short steps for getting better Hebrew and English voices on Android, iPhone and Windows. Characters change voice, pace, pauses and wording; they are not recordings of real people and cannot copy real accents. In the Android app you can also pick the voice engine (Google, Samsung, or a free offline neural engine such as SherpaTTS or Hayai TTS that you install separately) and then a voice from it.']],
    ['Privacy', ['All data stays on your device. Use Settings → Back up all data to save or move it.']],
  ],
  he: [
    ['התחלה מהירה', ['פתחו שגרות ולחצו התחל על שגרה לדוגמה, או צרו שגרה משלכם עם “שגרה חדשה”.', 'כל שגרה היא רשימת משימות. לכל משימה יש משך (דקות + שניות) והערכת זמן אופציונלית.']],
    ['בניית שגרה', ['לחצו על שגרה כדי לערוך. גררו את הידית ⋮⋮ (או השתמשו בחיצים / Alt+חץ) כדי לשנות סדר.', 'הערכת זמן = ההערכה שלכם לזמן האמיתי; השאירו ריק כדי להשתמש במשך. ברירות מחדל בהגדרות.', 'הכוכב מוסיף למועדפים - אלה מופיעים גם בווידג׳ט של אנדרואיד.']],
    ['הרצת שגרה', ['“התחל” מפעיל את המשימה הראשונה. הטבעת סופרת לאחור; 10 שניות לפני הסוף יש צפצוף קצר, ובסיום צפצוף ארוך (בהגדרות: צפצוף, רטט, שניהם, שקט).', '“סיימתי ✓” (או סימון התיבה) מעביר הלאה. השהיה, +דקה, דלג וסיום תמיד במרחק לחיצה. הזמן ממשיך להיספר כחריגה עד שלוחצים סיימתי.', 'הסיכום מציג שעת התחלה, מתוכנן מול הערכה מול בפועל וכל משימה. הרצה שבאמצע שורדת סגירת האפליקציה.']],
    ['סטטיסטיקות ותובנות', ['בסטטיסטיקות מופיעות השגרות שסיימתם: גרף של זמן כולל בכל הרצה (בפועל, מתוכנן, הערכה), ממוצעים וטבלה לפי משימה.', 'אחרי 3 הרצות מופיעות תובנות: משימות שמסתיימות תמיד מוקדם (לקצר) או מאוחר (להאריך), וההשפעה נטו על המסגרת הכוללת. “החל” מעדכן את המשך.']],
    ['התראת התחלה', ['שעוני התעוררות: בעורך הפעילו “הזכירו לי להתחיל” ובחרו שעה וימים. לשעון הראשון יש צליל, עוצמה, רטט, משך והודעה משלו; “הוספת שעון נוסף” (או “הוספת N שעונים נוספים כל M דקות”) מוסיפה עוד, כל אחד אחרי הפרש לפי בחירתכם ועם צליל, עוצמה, הודעה וקול מוקרא משלו - למשל 7:00, 7:15 ו-7:20. אחרי השעון האחרון בוחרים “להציע להתחיל” (כפתור התחלה) או “להתחיל את השגרה אוטומטית”. באנדרואיד: שעונים אמיתיים שמצלצלים גם כשהאפליקציה סגורה; בטלפון נעול האפליקציה נפתחת מעצמה, אחרת לחצו על ההתראה (כפתור התחלה בהתראה תמיד מתחיל). בדפדפן: רק כשהדף פתוח.']],
    ['הפרעות בלתי מתוכננות', ['הפרעות בלתי מתוכננות: בזמן שגרה לחצו ⚡ בלתי מתוכנן ובחרו מה קרה (שירותים, נשפך משהו, שכחתי משהו... או במילים שלכם). שעון השגרה נעצר והזמן הזה נספר בנפרד - לא כזמן משימה ולא כהשהיה - ואז לחצו “חזרה לשגרה”. הסיכום והסטטיסטיקה מראים כמה פעמים וכמה זמן. כשאותה הפרעה חוזרת בשגרה (לפחות ב-3 מההרצות האחרונות) כרטיס מציע להוסיף אותה לשגרה כמשימה אמיתית, או להסתכל מקרוב: כמה שאלות מנחות (למה, מה קורה לפני, דבר אחד לנסות) נשמרות ביומן והאפליקציה ממשיכה לספור ומראה אם זה משתנה.']],
    ['שיתוף', ['שיתוף יוצר קוד וקישור. שלחו דרך תפריט השיתוף (בלוטות׳, Nearby Share, וואטסאפ), העתיקו, או כתבו לתג NFC. ייבוא מקבל קוד, קישור, קובץ טקסט או תג NFC.', 'אין שרת: הכול עובר ישירות ונבדק בהגעה.']],
    ['עידוד, כוכבים ומסך', ['הגדרות ← שם והחבר שלי: האפליקציה מעודדת אתכם בשם עם הודעות שמחות, אימוג׳ים ואנימציות (אפשר לכבות או להקריא בקול בהגדרות).', 'סיום שגרה מזכה עד 3 כוכבים (הכול הושלם במסגרת התכנון = 3). סיום שגרה אחת לפחות ביום בונה רצף 🔥 שמוצג במסך הבית.', 'השהיה היא הכפתור הגדול ליד סיימתי: השעון נעצר וזמן ההשהיה מוצג בסיכום. הצ׳יפ ☀️ במסך הבית (או בהגדרות) משאיר את המסך דלוק כל עוד האפליקציה פתוחה, כדי ללחוץ על התקדמות בכל רגע.']],
    ['מאמן מיינדפולנס וקול', ['הגדרות ← עליך: הוסיפו שם, גיל ומגדר - ההודעות והטיפים יפנו אליכם (בעברית בצורת הזכר/נקבה הנכונה) בטון שמתאים לגיל.', 'לחצו 💡 טיפ (ליד השהיה) או על ה-💡 בכל משימה לקבלת רעיון קצר מ-CBT / מיינדפולנס: נשימה, חזרה להווה, בדיקת מחשבות מדאיגות, לתת למחשבות לעבור, חמלה עצמית, ריכוז ולחץ זמן. “עוד טיפ” מביא חדש.', 'הפעילו “טיפים אוטומטיים” והמאמן יציע טיפ כשמשימה חורגת, כשמתאחרים 3 דקות ויותר, או כשנשארים מושהים 2 דקות. בהגדרות ← קול בחרו אם הודעות העידוד והטיפים יהיו טקסט בלבד או גם יוקראו אוטומטית בקול (אותו טון, שם ופניה לפי המגדר), ואז בחרו קול וסגנון (עמוק, גבוה, רובוט, סנאי, ענק, מנומנם, גיבור על, פיה). הסגנונות משנים גובה וקצב של קול הטלפון; אם אין קול בעברית, התקינו אחד בהגדרות הטקסט-לדיבור של הטלפון.', 'המאמן נותן רעיונות כלליים לרווחה, לא טיפול. אם החרדה מציפה, פנו למבוגר מהימן או לאיש מקצוע.']],
    ['העברת נתונים בין האפליקציה לאתר', ['האתר (PWA) ואפליקציית האנדרואיד שומרים נתונים בנפרד. להעברת שגרות, היסטוריה והגדרות ביניהם: הגדרות ← העברת נתונים ← שמירת קובץ גיבוי / העתקת קוד סנכרון / שליחה…, ואז בשני ← ייבוא גיבוי (קובץ, או הדבקת הקוד).', 'מיזוג שומר את הגרסה החדשה יותר של כל שגרה ומוסיף היסטוריה חסרה, ואינו מוחק. החלפה הופכת את המכשיר להעתק מדויק של הגיבוי. סמנו “לייבא גם הגדרות” כדי להעביר גם שם, קול והעדפות.']],
    ['שעת יציאה, קצב ונגישות', ['בעורך הגדירו “שעת יציאה”: בהרצה רואים אם תספיקו (זמן פנוי או איחור) ומקבלים אזהרה 10 ו-5 דקות לפני. “הצע שעת התחלה” קובעת את התראת ההתחלה כך שתסיימו בדיוק בזמן.', 'הגדרות ← קצב: מהיר מקצר כל משימה ב-30%; רגוע מסתיר אזהרות ומצב חריגה אדום, כך שאין לחץ זמן. “הקראת המשימה הבאה בקול” אומר “עכשיו: …” בכל משימה.', 'הגדרות ← נגישות: גודל טקסט, צבעים ידידותיים לעיוורון צבעים, ניגודיות גבוהה והכרזות לקורא מסך (TalkBack). למשימות אפשר סטיקר או תמונה משלכם (לחצו על אייקון המשימה).']],
    ['משפחה: טלפון הורה וטלפון ילד', ['פתחו את לשונית משפחה. בטלפון של ההורה לחצו “הוספת ילד” והעבירו את ההזמנה לטלפון של הילד: הצמידו את שני הטלפונים (NFC, אפליקציית אנדרואיד), כתבו לתג NFC, שלחו בבלוטות׳ / Nearby Share / אפליקציית הודעות, או העתיקו. בטלפון של הילד לחצו “הצטרפות להורה”, הדביקו את ההזמנה ושלחו את התשובה חזרה; ההורה מאשר. הזמנה עובדת פעם אחת ופגה אחרי 24 שעות. אפשר גם להציג אותה כקוד QR לסריקה בטלפון השני.', 'אחרי הקישור ההורה רואה את הכוכבים, הרצף, השגרות האחרונות ומה הילד עושה ממש עכשיו; שולח שגרות, עידודים ויעד לפרס (20 כוכבים = גלידה, או “5 שגרות בזמן השבוע”) ומקבל התראה כשהילד מאחר (בחיבור חי). כשהיעד מושג הילד חוגג וההורה מקבל הודעה.', 'אין שרת: ההודעות מוצפנות ועוברות ישירות. עם “חיבור חי (Wi-Fi)” (שני הטלפונים באותה רשת) או חיבור הבלוטות׳ של אפליקציית האנדרואיד (קודם מצמידים את הטלפונים) העדכונים מיידיים; אחרת כל הודעה היא קוד שמעבירים בתג NFC, בתפריט השיתוף או בהעתק-הדבק.']],
    ['ווידג׳ט התקדמות (אנדרואיד)', ['הוסיפו את הווידג׳ט “התקדמות שגרה” ממסך הבית: הוא מציג את השגרה הפעילה, את המשימה הנוכחית, ספירה לאחור חיה ופס התקדמות, ופותח את האפליקציה בלחיצה.']],
    ['מצב פשוט, צבע מבטא והגדרות', ['הגדרות ← מראה ← “מצב פשוט לילדים” מציג רק את השגרות עם כפתורי התחלה גדולים. כל השאר (עריכה, הגדרות, סטטיסטיקות, משפחה) נעול מאחורי שאלה קצרה למבוגרים ל-10 דקות בכל פעם.', 'בחרו צבע מבטא לכל האפליקציה, וגם ערכת נושא בהירה/כהה, גודל טקסט, צבעים ידידותיים לעיוורון צבעים וניגודיות גבוהה. ההגדרות מקובצות לאזורים שאפשר לכווץ, והאפליקציה זוכרת מה פתוח.']],
    ['סיכום שבועי, היסטוריה ודוגמאות', ['בסטטיסטיקות מופיע “השבוע”: שגרות שהסתיימו, כוכבים, כמה בזמן, ימים פעילים והאם השתפרתם לעומת שבוע שעבר, וגם מפת חום של 5 שבועות. “שיתוף סיכום” שולח טקסט קצר; “ייצוא היסטוריה (CSV)” שומר כל הרצה לגיליון אלקטרוני.', 'מחיקת שגרה מאפשרת “ביטול” למספר שניות. הגדרות ← “הוספת עוד שגרות לדוגמה” מוסיפה שגרות שינה, שיעורי בית ואחרי בית הספר.']],
    ['אנשים, אווטרים ורמות', ['כמה אנשים יכולים לחלוק טלפון אחד: לחצו על האווטר במסך הבית (או הגדרות ← עליך) כדי להחליף אדם או להוסיף. לכל אדם יש שם, גיל, אווטר, היסטוריית שגרות, כוכבים, רצף, תגים וקישור להורה משלו.', 'בחרו אווטר: דמויות מונפשות (מצמצמות, מנופפות, חוגגות, רוקדות ונרדמות תוך כדי - שועל, חתול ופנדה מההתחלה, ועוד נפתחות בעליית רמה), אימוג׳י, תמונה משלכם, או GIF מונפש משלכם (עד 160 KB). תמונות ו-GIF נשארים בטלפון שלכם.', 'כוכבים מעלים את הרמה (מוצגת במסך הבית); רמות גבוהות פותחות דמויות חדשות.']],
    ['ימים, ציוד והישגים', ['בעורך, “לוח זמנים” קובע לאילו ימים השגרה מיועדת (ימי לימודים, סוף שבוע או ימים לבחירה); מסך הבית מציג קודם את שגרות היום. “ציוד לזכור” מוסיף דברים לימים מסוימים (ציוד ספורט, תיק בריכה): הם מופיעים כרשימת סימון בתחילת השגרה ונספרים בסיכום.', 'תגים (שגרה ראשונה, רצפים, בזמן, ציפור בוקר, מהירים, חזרה…) מתקבלים אוטומטית; חדשים נחגגים במסך הסיכום וכולם מופיעים בסטטיסטיקות ← הישגים.']],
    ['אפליקציית אנדרואיד וווידג׳ט', ['ווידג׳ט כרטיס שגרה: הוסיפו “כרטיס שגרה” מרשימת הווידג׳טים. הוא מציג שגרה שמורה עם המשימות, משכים, ימים, שעת יציאה וכמות ציוד; לחיצה עליו (או ▶ התחלה) מפעילה אותה באפליקציה עם כל ההגדרות השמורות. עם ‹ › בווידג׳ט מחליפים לשגרה אחרת (כל ווידג׳ט זוכר את שלו). בזמן שהשגרה רצה הכרטיס הופך לספירה לאחור חיה עם התקדמות.', 'הגדרות ← הורדת אפליקציית אנדרואיד נותנת תמיד את ה-APK העדכני. יש לאשר פעם אחת “התקנה ממקורות לא ידועים” לדפדפן.', 'לחיצה ארוכה על מסך הבית ← ווידג׳טים ← SonRise להפעלת שגרה מועדפת בלחיצה.']],
    ['כלי עזר: רוגע, ריכוז, יומן ופרסים', ['בחרו במה תרצו עזרה: מסך הבית ← “במה תרצו עזרה?” (או הגדרות ← כלי עזר). בחרו תחומים כמו ריכוז, רוגע, תחושת זמן, זכירה, מוטיבציה או הרגלים - והאפליקציה מפעילה כלים מתאימים. הורה יכול לבחור זאת עבור ילד מלשונית משפחה (🎯). כל כלי עדיין ניתן להפעלה או כיבוי בנפרד.', 'פינת רוגע (🌬️): קצבי נשימה, קרקוע 5-4-3-2-1 וסריקת גוף, 1-3 דקות, עם רטט עדין. בזמן שגרה היא עוצרת את השעון בזמן שנושמים. ספרינטים מחלקים משימות ארוכות לספרינטים קצרים עם הפסקת תנועה של 30 שניות; חניית מחשבות (🅿️) שומרת מחשבה תועה כדי לחזור למשימה; הרמז למשימה הבאה מראה מה הבא; שעון העוגה מציג זמן כעיגול שמתמלא; פרצופי מצב הרוח אחרי שגרה מזינים תובנה בסטטיסטיקה.', 'יומן (📓): הערות, הקלטות (🎙️ - גם תוך כדי משימה), בדיקות מחשבה, “3 דברים טובים” ומחשבות שנחנו. הוא נשמר רק במכשיר הזה ואינו חלק מגיבויים או משיתוף. סיסמה (אופציונלי): יומן ← סיסמה. היא נשמרת כגיבוב עם מלח והרשומות מוצפנות; הוספת הערה לעולם לא דורשת סיסמה. שכחתם? ענו על שתי שאלות האבטחה וקבעו חדשה. אם שכחתם גם אותן, אי אפשר לפתוח את הרשומות - רק למחוק.', 'דיבור לטקסט (אופציונלי): בהערה לחצו “הכתבה” (או הקלטה - בדפדפן יופיע תמלול מוצע בזמן שמדברים). זו רק הצעה: בדקו ותקנו. באפליקציית האנדרואיד נעשה שימוש בזיהוי הדיבור של הטלפון; בדפדפן שירות הדיבור שלו עשוי לשלוח אודיו ליצרן, ולכן האפליקציה שואלת קודם. תפריט פרסים (🎁): בזבוז כוכבים על פרסים מתפריט שאתם או ההורה הגדרתם; ההורה מקבל הודעה ויכול לסמן כ“ניתן”.']],
    ['עריכה קלה, ניסוחים ותוספות', ['עריכת משימות: לחצו על הזמן של משימה כדי לפתוח את גיליון הזמן (זמנים מהירים, כפתורי ±דקה/±15 שניות, דקות ושניות מדויקות), או השתמשו בכפתורי − / + לידו. תפריט ה-☰ בכל משימה מאפשר להוסיף משימה מתחת, לשכפל, להזיז למעלה/למטה/להתחלה/לסוף, להחליף תמונה או להסיר; גרירה בידית עדיין עובדת. תוכניות אם-אז (בעורך ← “תוכניות אם-אז”) מוצגות ככרטיס בתחילת השגרה: “אם מתחשק לי לגלול בטלפון, אז הוא נכנס למגירה”. הגדרות ← מראה ← “מראה השעון” מחליף את הטבעת לעוגה, לפס או לשעון חול. ילדים קטנים: כשהגיל נמוך מ-12 כל האפליקציה משתמשת בניסוח קליל וכיפי (הגדרות ← מראה ← “סגנון טקסטים” לכפות או לכבות). אנדרואיד: בהתראת השעון יש נודניק של 5 דקות, וווידג׳ט “פינת רוגע” פותח נשימה בלחיצה אחת. הורים רואים סיכום שבועי (השלבים האיטיים, הפרעות חוזרות) בכרטיס של כל ילד.']],
    ['תבניות', ['תבניות: שמרו משימות ושגרות שמשתמשים בהן שוב ושוב. בעורך של שגרה לחצו “שמירה כתבנית” (💾) לשגרה שלמה, או “שמירת משימה כתבנית” בתפריט ה-☰ של משימה. “הוספה מתבניות” פותח אריחים גדולים של המשימות השמורות שלכם ורעיונות מוכנים (בוקר, ערב, בית ספר, בית) - אפשר לחפש, לסנן וללחוץ על כמה שרוצים. במסך הבית “מתבנית” פותח שגרה חדשה מאחת התבניות שלכם או מרעיון מוכן. בית ← תבניות מנהל אותן: שימוש, שינוי שם, עריכת זמן, שיתוף ומחיקה (עם ביטול). התבניות נכללות ב“גיבוי כל הנתונים” ובקודי סנכרון.']],
    ['מטרות', ['מטרות (מטרה - תכנון - ביצוע - בדיקה): בית ← מטרות. כתבו מטרה אחת שחשובה לכם (“להיות מוכנים בזמן בלי תזכורות”), אפשר לקשור אותה לשגרה, ובחרו עד שלוש אסטרטגיות שמתאימות לכם - לזמן, תכנון, זכירה, קשב או ארגון - או כתבו משלכם. ביצוע: התוכנית מופיעה ככרטיס כשמתחילים את השגרה. בדיקה: אחרי השגרה מספרים לאפליקציה איך זה עבד (פרצוף וכמה מילים); האפליקציה מראה כמה שגרות היו בזמן מאז שהתחלתם והאם הבדיקות משתפרות, ומזכירה בדיקה שבועית. הורה יכול להציע מטרה מלשונית משפחה (“הצעת מטרה”), ו“שב איתי” מראה לילד שההורה איתו בזמן שגרה. בהשראת גישות ממוקדות מטרה ואסטרטגיות כמו קוג-פאן (ריפוי בעיסוק, האוניברסיטה העברית). זהו כלי עזר עצמי ואינו מחליף ריפוי בעיסוק או איש מקצוע אחר.']],
    ['מסך שעונים', ['מסך שעונים: בית ← שעונים מעוררים מציג כל שגרה עם שעון ההתעוררות שלה - הפעלה וכיבוי, הלוח (למשל 07:00 → 07:15 → 07:20) ועריכת כל השרשרת. גם כרטיס השגרה מציג את השעון שלה. אחרי עדכון מופיע חלון חד-פעמי “חדש ב…” שמצביע על החידושים.']],
    ['תחושות ועזרה במשימה', ['תחושות ועזרה בכל משימה: בזמן משימה אפשר לדרג כמה קשה היא באמצעות האייקונים (🪶 קל מאוד … 🥵 קשה מאוד). “למה קשה?” פותח הערה (הקלדה או הקלטה) שמקושרת למשימה - מה קשה ואילו מחשבות עלו. “מחשבה טובה” ו“הרפיה” נותנות הצעה אחרת בכל פעם, בניסוח שמתאים לגיל: מחשבות טובות (מאמץ, חמלה עצמית, ניסוח מחדש, התחלה קטנה) ותרגילים קצרים (נשימה, כיווץ ושחרור, ניעור, חמשת החושים, חיבוק פרפר ועוד); תרגילי נשימה יכולים לפתוח את פינת הרוגע. הכול נשמר עם ההרצה. סטטיסטיקה ← “איפה קשה?” מדרגת משימות לפי קושי ממוצע, מסמנת את אלה שגם קשות וגם איטיות, וסופרת כמה פעמים השתמשו בהערות, מחשבות טובות והרפיה - כדי לראות איפה צריך יותר עזרה.']],
    ['דוחות, PDF ומייל', ['דוחות, PDF ומייל: סטטיסטיקה ← “ייצוא ושליחה” (או 📄 ליד כל הרצה בהיסטוריה של שגרה, או במסך הסיכום) פותח דוח מעוצב עם סיכום, תובנות במילים פשוטות, גרפים לאורך זמן, לוח פעילות, טבלאות לפי שגרה ולפי משימה, קושי, הפרעות, מצב רוח ומטרות - להרצה אחת או ל-7/30/90 הימים האחרונים או לכל התקופה, לכל השגרות או לשגרה אחת. “שמירה כ-PDF” יוצרת קובץ PDF אמיתי; “שליחת הדוח במייל” פותחת את אפליקציית המייל עם ה-PDF מצורף (באפליקציית האנדרואיד, או בטלפונים שתומכים בשיתוף קבצים) - בדפדפן ה-PDF יורד והמייל נפתח עם סיכום, ואתם מצרפים את הקובץ. יש גם הדפסה והעתקת סיכום. הדוחות נוצרים במכשיר הזה בלבד.']],
    ['זמנים חכמים ושלבי ביניים', ['זמנים חכמים ושלבי ביניים: בעורך של שגרה, “זמנים חכמים” מציע משך לכל משימה - לפי הרצות קודמות שלכם כשיש (זמן טיפוסי, מעט יותר אם בדרך כלל חורגים), ואחרת הערכה הגיונית לסוג המשימה מותאמת לגיל ולעזרה שבחרתם (ריכוז, רוגע, זמן, זכירה). גם מתחת לשם משימה מופיע רמז קטן “בערך 8 דק׳”. “שלבי ביניים חכמים” מציע שלבים קצרים שמתאימים לעזרה שבחרתם - לחרדה נשימה מרגיעה בהתחלה ובדיקת רוגע לפני משהו ארוך או קשה; לקשב בחירת דבר אחד להתחיל ממנו, הפסקת תנועה אחרי רצף ארוך, פינוי שולחן לפני שיעורי בית; לזכירה אמירת השלבים בקול ובדיקה אחרונה. כל הצעה מראה למה; מסמנים מה שרוצים. הורה יכול לבחור “הצעה עבור” ילד מקושר. שלבים שנוספו כך מציעים תרגיל בלחיצה אחת כשהם מגיעים בזמן השגרה.']],
    ['כלי קוג-פאן, גרסה ודוחות HTML', ['עוד כלים בהשראת קוג-פאן: סטטיסטיקה ← “עד כמה ההערכות שלי מדויקות?” משווה את הזמן שהערכתם למשימות למה שקרה באמת ואומרת אם נוטים להעריך קצר או ארוך ואם מתקרבים. בבדיקה של מטרה מסמנים באילו אסטרטגיות השתמשתם - והמטרה מראה איזו הלכה הכי טוב. הורים מקבלים בלשונית משפחה שאלה מנחה יומית “שואלים, לא אומרים”. שעונים מעוררים פעילים כברירת מחדל לשגרות חדשות ומוכנות (בית ← שעונים מעוררים), מספר הגרסה מופיע בתחתית מסך הבית ובהגדרות, ו“מה חדש” מפרט מה השתנה. אפשר לשמור דוחות גם כקובץ HTML אינטראקטיבי אחד עם אנימציות (לשוניות ל-7/30/90 ימים ולכל התקופה, מספרים שסופרים, עמודות וגרפים שמציירים את עצמם, חלקים מתקפלים; עובד גם בלי אינטרנט ונראה טוב בהדפסה).']],
    ['מסתכלים אחורה', ['מסתכלים אחורה (רטרוספקטיבה): אחרי הרצה לוחצים “להסתכל אחורה” במסך הסיכום (או 🔄 בהיסטוריה של שגרה, או ההצעה במסך הבית - קודם ההרצה שהכי הרבה קרה בה, ואפשר גם ימים אחר כך). קודם בוחרים איך: מונחה (שלב אחד בכל פעם, אפשר לעצור ולהמשיך אחר כך) או חופשי (הכול בדף אחד); על ההרצה הזו או על 5 ההרצות האחרונות של השגרה (התמונה הרגילה); את הכול או רק חלק (איך הרגשנו, משימות, מה הלך טוב, מה לשנות) - את השאר אפשר לעשות בהסתכלות נוספת, ואפשר לעשות כמה הסתכלויות שרוצים על אותה הרצה. לכל משימה בוחרים הלך טוב, נתקע או לא עכשיו; איפה שנתקע בוחרים למה (קשה להתחיל, הסחות דעת, גדול או לא ברור, עייפות, לא מצאתי משהו, דאגות, לא מספיק זמן). האפליקציה מציעה שינויים מוחשיים בשגרה הזו - יותר זמן, שלב עזר לפני המשימה, פיצול משימה, שעון מוקדם יותר, פריט ציוד, היערכות להפרעה, מטרה עם תוכנית - ומחילים את מה שסימנתם בלחיצה (אפשר לבטל כל אחד). אחרי שמחילים שינויים האפליקציה משווה את ההרצות הבאות של השגרה לקודמות (בזמן, חריגה מהתוכנית, קושי, משימות שנתקעו, הפרעות) ואומרת אם זה עזר, הידרדר או לא שינה בבירור - אחרי 3 הרצות, ואז כרטיס במסך הבית מודיע. בית ← מסתכלים אחורה מציג על מה להתמקד (משימות שממשיכות להיתקע או הונחו בצד), מה עבד ומה לא, מה מפריע, טיוטות להשלים ומסקנות אוטומטיות; הגדרות ← כלי עזר מאפשרת לקבוע את הסגנון הרגיל שלכם. התוצאות נכללות בדוחות (PDF ו-HTML) ובגיבויים.']],
    ['שעונים, ימי חופש וסרגל הכלים', ['שעונים, ימי חופש וסרגל הכלים: בבית יש סרגל כלים אחד - חדשה, אשף, תכנון, רוגע, מעקב ושעונים. תכנון, רוגע ומעקב פותחים רשימה קצרה מתחת לסרגל; כפתור השעונים משהה את כל השעונים (עד מחר, לשבוע, או עד שתפעילו). בכל כרטיס שגרה יש מתג שעון ומדבקת ⏰ כשיש שעון. בשעון בוחרים סוג צלצול (נוגעים באריח כדי לשמוע; באפליקציית האנדרואיד גם צליל מהטלפון), ומשאירים "שקט בחגים ובחופשות" פעיל כדי שלא יצלצל בחגי ישראל ובחופשות, כולל החופש הגדול. בבית מופיעים התאריך העברי והחג של היום.']],
    ['פינת רוגע: סריקות גוף ודמיון מודרך', ['פינת רוגע: סריקות גוף ודמיון מודרך: בוחרים נשימה, 5-4-3-2-1, סריקת גוף או דמיון מודרך. לסריקת הגוף ארבעה סוגים: מהירה, מלאה (מהראש עד הרגליים), כיווץ ושחרור, ולשינה. בדמיון המודרך 11 מסעות קצרים - ארבעת היסודות (אדמה, אוויר, מים, אש), מקום בטוח, גלים, יער, הר, עלים על נחל, בלון דאגות, קופסת דאגות, אור חם, ענן מרחף ועוזר טוב - מוצגים צעד אחרי צעד ואם רוצים גם מוקראים בקול. אלה תרגילי הרפיה, לא טיפול.']],
['תיעוד מצב (אפר״ת)', ['תיעוד מצב (אפר״ת): דרך להבין רגעים קשים, מעולם ה-CBT. ארבע שאלות קצרות - אירוע (מה קרה), פרשנות (מה אמרתי לעצמי), רגש (מה הרגשתי ועד כמה חזק) ותגובה (מה עשיתי) - ושלב אופציונלי לדרך אחרת להסתכל. אפשר לכתוב, להכתיב או להקליט. מוצאים את זה ביומן ← התבוננות, בכרטיס העזרה במשימה (לתעד את הרגע), בסוף תרגיל רוגע, או בחיפוש. אחרי שלושה תיעודים היומן מסכם את הדפוסים (רגשות, מלכודות חשיבה, מה מקל). זה פרטי למכשיר הזה והוא סקירה לעזרה עצמית, לא אבחנה.']],
['מטרות בתוך שגרות והאשף', ['מטרות בתוך שגרות והאשף: אפשר לקשר מטרה לשגרה (כרטיס השגרה מציג תגית 🎯, בעריכה יש אזור מטרה, ובמסך הריצה מוצגת התוכנית). באשף, שלב המטרה מאפשר לבחור או ליצור מטרה, והמטרה מוסיפה את האסטרטגיות שלה כשלבים הראשונים של השגרה החדשה. בשלב הסיכום אפשר לשנות שמות, לשנות זמנים, להסיר שלבים ולהוסיף שלבים משלכם לפני היצירה. מכל מטרה, "בניית שגרה למטרה הזו" פותח את האשף.']],
    ['להתחיל מחדש, לבטל או למחוק ריצה', ['להתחיל מחדש, לבטל או למחוק ריצה: שגרה שבאמצע אף פעם לא תקועה. במסך הריצה פותחים עוד ← שינוי התוכנית: "להתחיל מההתחלה" מתחיל שוב מהמשימה הראשונה, ו"ביטול הריצה" יוצא בלי לשמור כלום. אותם שני כפתורים יש בכרטיס ה"המשך" בבית. שום דבר מריצה שבוטלה או התחילה מחדש לא נכנס להיסטוריה. ריצה שהסתיימה אפשר למחוק ממסך הסיכום (מחיקת הריצה) ולהחזיר עם ביטול פעולה.']],
    ['למה האפליקציה משמשת, אנשים ופקודות קוליות', ['למה האפליקציה משמשת: בהגדרות ← למה האפליקציה משמשת בוחרים דרך עבודה (CBT, Cog-Fun) ו/או מה קשה (קשב, חרדה, התארגנות, מוטיבציה) וגיל, והאפליקציה מציגה רק את מה שמתאים. “להציג הכול” מחזיר הכול בכל רגע.', 'אנשים: לכל אדם הגדרות, מראה ותצוגה משלו. מחליפים מהתפריט הקטן למעלה, מוסיפים שם, או מנהלים את כולם בהגדרות ← אנשים. כשיש כמה אנשים האפליקציה יכולה לשאול מי משתמש בתחילת הביקור.', 'הגדרות: בראש ההגדרות יש תיבת חיפוש וסרגל קפיצה. תחת מראה בוחרים עיצוב, טקסט קל לקריאה או צבע משלכם. את מסכי הפתיחה וההגדרה אפשר לפתוח שוב מההגדרות.', 'פקודות קוליות: במהלך שגרה לוחצים על “האזנה לפקודות” ואומרים משפט קצר כמו סיימתי, תוספת זמן, השהה, המשך, דלג, יומן, פינת הרוגע, הזכר לי את השלב, כמה זמן נשאר או עצור (תמיד שואל קודם; עונים כן או לא). ההאזנה נמשכת לאורך כל השלבים. לחיצה על ? מציגה את כל הפקודות, והן רשומות גם בהגדרות ← פקודות קוליות.']],
    ['שיתוף בין אנשים, משימות מיוחדות, ניקוד והעברת שגרות', ['מי רואה שגרה: כשיש כמה אנשים במכשיר, פותחים שגרה ובקטע “מי רואה את השגרה” בוחרים כולם או רק אנשים מסוימים (הורה או מטפל יכולים להגדיר שגרות לילדים באותו טלפון). שעונים מעוררים ממשיכים לצלצל במכשיר.', 'משימות מיוחדות: בעורך השגרה לוחצים “הוספת משימה מיוחדת” ובוחרים לפי נושא או בחיפוש: כתיבה ביומן, אחסון מחשבה, סריקת גוף, דמיון מודרך, הרפיה, הערה קולית ועוד. במסך השגרה המשימה מציגה כפתור גדול אחד שפותח את הכלי.', 'ניקוד: הגדרות ← ניקוד ופרסים. ניקוד אוטומטי לפי הזמן המתוכנן, או שקובעים את הניקוד של כל שלב. סיום מוקדם מוסיף בונוס, סיום מאוחר מוריד קצת (אף פעם לא מתחת ל-0, לא בקצב הרגוע, ואפשר לכבות). אפשר לתת לשלב פרס (מדליה, מטבע, גביע, כוכב, יהלום, כתר) שזוכים בו בסיום לפני הזמן, עם כפל נקודות. בסוף יש פודיום עם זיקוקים של הניקודים הטובים שלכם בשגרה, והסטטיסטיקה מציגה נקודות לאורך זמן וסכום מצטבר.', 'העברת שגרות: בית ← תכנון ← שיתוף והעברת שגרות. מעתיקים שגרות לאדם אחר במכשיר, שומרים לקובץ (או שולחים בווטסאפ או במייל) ומכניסים שגרות מקובץ לאדם שבוחרים. שגרות שמוכנסות מגיעות עם שעון מעורר כבוי.']],
    ['תצוגת ילדים ותצוגה מלאה', ['ליד כפתור “מי משתמש באפליקציה” למעלה יש כפתור: “תצוגת ילדים” מעביר בלחיצה אחת לתצוגת ילדים (רק שגרות וכפתור התחלה גדול). בתצוגת ילדים הסרגל העליון מציג רק “תצוגה מלאה”, שמבקש שאלת מבוגר קצרה לפני שמחזיר הכול. הבחירה נשמרת לכל אדם בנפרד.']],
    ['כלי NLP ואנימציות רגועות', ['בהגדרות ← למה האפליקציה משמשת אפשר לבחור ב-NLP כדרך עבודה, לצד CBT ו-Cog-Fun. בבית ← רוגע ← כלי NLP יש שישה תרגילים קצרים ומודרכים: מטרה ברורה, דרך אחרת להסתכל (מסגור מחדש), עוגן מרגיע, מילים מדויקות (מציאת מילים גדולות כמו “תמיד” ו“לא יכול”), נקודות מבט וחזרה מנטלית. כל תרגיל שואל כמה שאלות, אחת בכל פעם, ואפשר לשמור את התשובות ביומן. אפשר גם להוסיף אותם לשגרה כמשימות מיוחדות; במסך השגרה המשימה פותחת את התרגיל.', 'NLP היא קבוצה פופולרית של טכניקות אימון, אבל הראיות המחקריות לה מוגבלות ומעורבות: אלה תרגילי התבוננות עצמית עדינים, לא טיפול ולא הבטחה לתוצאות. בהגדרות ← נגישות ← אנימציות רגועות מכבה תנועה כמו זיקוקים, קונפטי וקפיצות.']],
    ['סטודיו אווטרים והאווטרים שלי', ['פותחים את בורר האווטר (הגדרות ← עליך ← אווטר, או בעריכת אדם) ולוחצים “בונים אווטר משלי”, או פותחים “האווטרים שלי”. בסטודיו תצוגה חיה למעלה מראה את האווטר; אפשר לנסות את האנימציות (מנוחה, נפנוף, שמחה, ריקוד, שינה, הפתעה, חשיבה) ואת התחושות (שמח, רגוע, עצוב, מודאג, מתוסכל, עייף, נרגש, גאה). בוחרים לשונית: פנים, שיער, עיניים ופה, בגדים, תוספות, חבר ורקע, או צבעים. אפשרויות עם מנעול נפתחות ברמות גבוהות יותר. “הפתיעו אותי” בוחר אווטר אקראי. נותנים שם ושומרים, או “להשתמש כאווטר שלי”.', 'האווטרים שלי מציג את העיצובים השמורים: שימוש, עריכה, שכפול, שיתוף או מחיקה (ביטול ממש שם). שיתוף שולח קוד קצר בוואטסאפ, במייל או בלוח; “הוספה מקוד” מציג את האווטר לפני ההוספה. האווטרים השמורים נכללים בקובץ הגיבוי.']],
    ['מראות שקט ובולט', ['בהגדרות ← מראה יש עכשיו גם “שקט” (משפחת צבעים רכה אחת, גירוי נמוך, למי שהצבעים מציפים אותו) ו“בולט” (ניגודיות חזקה, מסגרת מיקוד ומסגרות עבות, לקשיי קשב ולראייה חלשה), בבהיר ובכהה.']],
    ['עדכונים ושיתוף האפליקציה', ['עדכונים ושיתוף האפליקציה: אפליקציית הרשת מתעדכנת מעצמה - בכניסה וכל שעה - ועוברת לגרסה החדשה לבד כשאין שום דבר רץ; אם אתם באמצע משהו היא שואלת קודם. אפליקציית האנדרואיד מתעדכנת מההורדה האחרונה. כדי לשתף את SonRise פותחים הגדרות ← אפליקציה ← שיתוף (או מחפשים "שיתוף"): בוחרים אפליקציית אנדרואיד או אפליקציית רשת, ושולחים בוואטסאפ, במייל, בתפריט השיתוף או בקישור מועתק.']],
    ['חיפוש, אשף והצעות', ['חיפוש, אשף והצעות: לוחצים על 🔍 (בסרגל התחתון או בבית, או Ctrl+K) וכותבים מה רוצים, למשל "שעון", "קול" או שם של שגרה - לוחצים על תוצאה ומגיעים ישר. האשף (בית ← עזרו לי לבנות, או חיפוש "אשף") שואל למי, בני כמה, מה עוזר, איזו שגרה ומתי, ובונה שגרה עם זמנים מתאימים והפסקות קצרות לרוגע ולריכוז. מדי פעם יופיע בבית רעיון עדין אחד; אפשר לבחור לנסות, לא עכשיו או לא להציג שוב (בהגדרות אפשר לכבות הצעות). המסכים שקטים: את שאר הכלים מוצאים תחת "עוד".']],
    ['קולות', ['קולות: הגדרות ← כלי עזר/קול. בוחרים דמות: קולות יומיומיים (אישה, גבר, ילדה, ילד, סבתא, סבא), סגנונות דיבור (מאמן, מדריכה רגועה, מספר סיפורים, מגיש רדיו, מורה) או דמויות מצחיקות (חתול, כלב, אריה, צפרדע, שודד ים, דינוזאור, רובוט, פיה) - חיות אומרות קודם את הצליל שלהן (“מיאו”). כל דמות בוחרת קול מותקן מתאים (גברי או נשי, הטבעי ביותר קודם, ודמויות אחרות משתמשות בקול אחר כשיש במכשיר יותר מאחד), מדברת במשפטים עם הפסקות טבעיות והטעמה עולה או יורדת בקצב אנושי ורגוע, ולא מקריאה אימוג\'י או קיצורים. אפשר עדיין לבחור קול מסוים במכשיר (★ מסמן קולות טבעיים/עצביים), לקבוע קצב דיבור וסגנון ניסוח (חברי, חם ומסורתי, מנומס ורשמי) שמוסיף פתיח קצר מדי פעם. כל בחירה מנגנת דוגמה. כמה אנושי זה נשמע תלוי בעיקר בקולות המותקנים במכשיר - בהגדרות יש צעדים קצרים להשגת קולות טובים יותר בעברית ובאנגלית באנדרואיד, באייפון וב-Windows. הדמויות משנות קול, קצב, הפסקות וניסוח; הן לא הקלטות של אנשים אמיתיים ולא יכולות לחקות מבטאים אמיתיים. באפליקציית האנדרואיד אפשר גם לבחור מנוע קול (גוגל, סמסונג, או מנוע עצבי חינמי כמו SherpaTTS או Hayai TTS שמתקינים בנפרד) ואז קול מתוכו.']],
    ['פרטיות', ['כל הנתונים נשארים במכשיר. הגדרות ← גיבוי כל הנתונים לשמירה או להעברה.']],
  ],
};

export function renderGuide(root) {
  setChildren(root, h('h1', {}, t('guideTitle')), ...GUIDE[getLang()].map(([title, paras]) =>
    h('section', { class: 'card guide' }, h('h2', {}, title), paras.map((p) => h('p', {}, p)))));
  return () => {};
}
